when:



  %%TOKEN_URL%%
  POST

    application/x-www-form-urlencoded

  @{
    return "grant_type=client_credentials" +
           "&client_id=%%CLIENT_ID%%" +
           "&client_secret=" + System.Net.WebUtility.UrlEncode((string)context.Variables["ccofBackendSecret"]) +
           "&scope=" + System.Net.WebUtility.UrlEncode("%%SCOPE%%");
  }


<set-variable name="ccofBackendToken" value="@{
    var response = context.Variables.ContainsKey("ccofBackendTokenResponse") ? context.Variables["ccofBackendTokenResponse"] as IResponse : null;
    if (response == null || response.StatusCode != 200) { return ""; }
    try {
        var token = response.Body.As()["access_token"];
        return token != null && token.Type == JTokenType.String ? (string)token : "";
    } catch {
        return "";
    }
}" />






      @("Bearer " + (string)context.Variables["ccofBackendToken"])
